# Code generated by Claude
"""
The eagle camera's placeholder mount (design plan 14.1, decisions-log M161): a search over the camera's tilt (pitch) and a few mount spots on top of the torso.

    MUJOCO_GL=egl python experiments/camera_mount_search.py [--out docs/reports]

At the TASK_CFG stance and pedestal command (TASK_CFG["pedestal_q"]), with both arms at the zombie pose and the fingers open, the camera faces straight forward (no roll) and every candidate is judged by:
  1. both hands (tool point, hand origin, finger tips) and the beaker's and the hotplate's corners (src/task_beaker_hotplate.framing_points) inside the image with at least 10 % of the image width and
     height to every edge (STANCE_REQUIREMENTS["framing_min_slack"]);
  2. the robot hides none of the beaker and at most 20 % of the hotplate (a segmentation render, src/stance_checks.OcclusionMeter, STANCE_REQUIREMENTS["occlusion_max_hidden"]);
  3. the camera's collision box is at least 5 mm from everything at the zombie pose (the torso link it is mounted on excepted).
Among the candidates that pass everything the one with the largest smallest margin wins. If none does, the closest candidate and what fails are reported and the script exits with 1.
Writes data/camera_mount_search.json, a sample eagle image and a side and a top picture of the mount (to --out).
"""

import argparse
import itertools
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import cv2  # noqa: E402
import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.stance_checks import OcclusionMeter  # noqa: E402
from src.task_beaker_hotplate import framing_points, home_targets, load_task, spawn_and_settle, yaw_to_quat  # noqa: E402
from src.task_config import STANCE_REQUIREMENTS, TASK_CFG  # noqa: E402

BOX_CLEARANCE = 0.005                                  # m: the camera box at least this far from everything (David 2026-10-22, part C)
PITCHES = tuple(range(0, 66, 5))                      # degrees below the horizontal
DX = (-0.08, -0.04, 0.0, 0.04, 0.08)                  # m: forward / back of the first guess
DZ = (0.0, 0.04, 0.08, 0.12)                              # m: higher than the first guess


def place_stance(sim):
    """The robot at the TASK_CFG stance, pedestal at its command, both arms at the zombie pose, fingers open (kinematics)."""
    model, data = sim.model, sim.data
    z = float(data.qpos[2])
    data.qpos[0:7] = [*TASK_CFG["staging_xy"], z, *yaw_to_quat(TASK_CFG["staging_yaw"])]
    for jn in robot_specs.PEDESTAL_SPECS["joints"]:
        data.qpos[model.joint(jn).qposadr[0]] = TASK_CFG["pedestal_q"]
    home = home_targets(model, TASK_CFG)
    for side in ("left", "right"):
        ids = arm_ids(model, side)
        for a, q in zip(ids["qadr"], home[side]):
            data.qpos[a] = q
        for j_ in ids["finger_jnt"]:
            data.qpos[model.jnt_qposadr[j_]] = 0.044
    mujoco.mj_forward(model, data)


def set_mount(model, data, pos, pitch_deg):
    b = model.body(robot_specs.EAGLE_BODY_SPECS["name"]).id
    p = math.radians(pitch_deg)
    model.body_pos[b] = pos
    model.body_quat[b] = [math.cos(p / 2), 0.0, math.sin(p / 2), 0.0]
    mujoco.mj_forward(model, data)


def margins(model, data, pts):
    """Margin of each point to the nearest image edge (fraction of the image; -1 if closer than 5 cm to the camera): the camera looks along -z of its own frame."""
    c = model.camera("eagle_cam").id
    pos, R = data.cam_xpos[c], data.cam_xmat[c].reshape(3, 3)
    W, H = model.cam_resolution[c]
    names = list(pts)
    pc = (np.array([pts[n] for n in names]) - pos) @ R
    depth = -pc[:, 2]
    th = math.tan(math.radians(float(model.cam_fovy[c])) / 2)
    u, v = pc[:, 0] / np.maximum(depth, 1e-6) / (th * W / H), pc[:, 1] / np.maximum(depth, 1e-6) / th
    m = np.where(depth < 0.05, -1.0, np.minimum((1 - np.abs(u)) / 2, (1 - np.abs(v)) / 2))
    return {n: float(m[i]) for i, n in enumerate(names)}


def box_clearance(model, data, others):
    box = model.geom(robot_specs.EAGLE_BODY_SPECS["name"] + "_box").id
    ft = np.zeros(6)
    best = (9.0, None)
    for g in others:
        d = mujoco.mj_geomDistance(model, data, box, g, 0.05, ft)
        if d < best[0]:
            best = (d, g)
    return best


def main(out):
    out = Path(out)
    sim = load_task(cameras=True)
    model, data = sim.model, sim.data
    spawn_and_settle(sim)
    place_stance(sim)
    body = model.body(robot_specs.EAGLE_BODY_SPECS["name"]).id
    base_pos = np.array(robot_specs.EAGLE_MOUNT["pos"], float)
    l0 = model.body(robot_specs.EAGLE_MOUNT["parent"]).id
    box = model.geom(robot_specs.EAGLE_BODY_SPECS["name"] + "_box").id
    others = [g for g in range(model.ngeom) if (model.geom_contype[g] or model.geom_conaffinity[g]) and g != box and int(model.geom_bodyid[g]) != l0
              and int(model.geom_type[g]) != int(mujoco.mjtGeom.mjGEOM_PLANE)]
    meter = OcclusionMeter(model)
    lim = STANCE_REQUIREMENTS["occlusion_max_hidden"]
    need = STANCE_REQUIREMENTS["framing_min_slack"]
    rows = []
    for dx, dz, pitch in itertools.product(DX, DZ, PITCHES):
        pos = base_pos + np.array([dx, 0.0, dz])
        set_mount(model, data, pos, pitch)
        mg = margins(model, data, framing_points(model, data))
        worst = min(mg, key=mg.get)
        clr, who = box_clearance(model, data, others)
        rows.append({"pos": pos.round(4).tolist(), "pitch_deg": pitch, "min_margin": mg[worst], "worst_point": worst, "box_clearance_mm": 1000 * clr,
                     "box_nearest": None if who is None else model.geom(who).name or model.body(int(model.geom_bodyid[who])).name})
    print(f"{len(rows)} candidates; margins and clearance done")
    for r in rows:
        r["margin_ok"] = r["min_margin"] >= need - 1e-9
        r["clear_ok"] = r["box_clearance_mm"] >= 1000 * BOX_CLEARANCE
        if r["margin_ok"] and r["clear_ok"]:
            set_mount(model, data, np.array(r["pos"]), r["pitch_deg"])
            occ = meter.measure(data)
            r["beaker_hidden"], r["hotplate_hidden"] = occ["beaker_hidden_frac"], occ["hotplate_hidden_frac"]
            r["occ_ok"] = all(occ[f"{n}_hidden_frac"] <= lim[n] + (1e-12 if lim[n] == 0 else 0) for n in lim)
        else:
            r["occ_ok"] = False
    good = [r for r in rows if r["margin_ok"] and r["clear_ok"] and r["occ_ok"]]
    result = {"stance": [*TASK_CFG["staging_xy"], TASK_CFG["staging_yaw"], TASK_CFG["pedestal_q"]], "margin_needed": need, "box_clearance_needed_mm": 1000 * BOX_CLEARANCE, "n": len(rows),
              "n_margin_ok": sum(r["margin_ok"] for r in rows), "n_clear_ok": sum(r["clear_ok"] for r in rows), "n_all_ok": len(good), "candidates": rows}
    print(f"margin ok: {result['n_margin_ok']}, box clearance ok: {result['n_clear_ok']}, everything ok: {len(good)}")
    if good:
        best = max(good, key=lambda r: (r["min_margin"], r["box_clearance_mm"]))
        verdict = "chosen"
    else:                                                           # the closest: the largest smallest margin, then the most clearance, whatever fails
        best = max(rows, key=lambda r: (min(r["min_margin"], need) + min(r["box_clearance_mm"] / 1000, BOX_CLEARANCE) + (1.0 if r.get("occ_ok") else 0.0), r["min_margin"]))
        verdict = "closest (nothing passes everything)"
    result["best"], result["verdict"] = best, verdict
    print(f"{verdict}: {json.dumps(best)}")
    for r in sorted(rows, key=lambda r: -r["min_margin"])[:8]:
        print("  top by margin:", {k: (round(v, 4) if isinstance(v, float) else v) for k, v in r.items()})
    tmp = PROJECT_ROOT / "data" / "camera_mount_search.json.tmp"
    tmp.write_text(json.dumps(result, indent=1, default=float))
    tmp.replace(PROJECT_ROOT / "data" / "camera_mount_search.json")

    # pictures of the best candidate
    set_mount(model, data, np.array(best["pos"]), best["pitch_deg"])
    out.mkdir(parents=True, exist_ok=True)
    W, H = [int(v) for v in model.cam_resolution[model.camera("eagle_cam").id]]
    r = mujoco.Renderer(model, H, W)
    r.update_scene(data, camera="eagle_cam")
    img = r.render().copy()
    mg_pts = framing_points(model, data)
    c = model.camera("eagle_cam").id
    pos, R = data.cam_xpos[c], data.cam_xmat[c].reshape(3, 3)
    th = math.tan(math.radians(float(model.cam_fovy[c])) / 2)
    for n, p in mg_pts.items():
        pc = (np.asarray(p) - pos) @ R
        if -pc[2] > 0.05:
            px, py = (pc[0] / -pc[2] / (th * W / H) + 1) / 2 * W, (1 - pc[1] / -pc[2] / th) / 2 * H
            cv2.circle(img, (int(px), int(py)), 4, (255, 0, 0), 1)
    marg = int(0.10 * W), int(0.10 * H)
    cv2.rectangle(img, (marg[0], marg[1]), (W - marg[0], H - marg[1]), (0, 200, 0), 1)
    cv2.imwrite(str(out / "eagle_view_fixed.png"), cv2.cvtColor(img, cv2.COLOR_RGB2BGR))
    r.close()
    # side and top views of the mount (the head's group is drawn)
    vopt = mujoco.MjvOption()
    vopt.geomgroup[5] = 1
    vopt.geomgroup[3] = 0
    views = []
    rr = mujoco.Renderer(model, 480, 480)
    look = data.xpos[body].copy()
    for az, el, label in ((90, -5, "front"), (0, -89, "top"), (180, -5, "side (robot left)")):
        cam = mujoco.MjvCamera()
        cam.type = mujoco.mjtCamera.mjCAMERA_FREE
        cam.lookat[:] = look
        cam.distance, cam.azimuth, cam.elevation = 0.9, az, el
        rr.update_scene(data, camera=cam, scene_option=vopt)
        im = rr.render().copy()
        cv2.putText(im, label, (8, 20), cv2.FONT_HERSHEY_SIMPLEX, 0.55, (0, 0, 0), 1)
        views.append(im)
    rr.close()
    cv2.imwrite(str(out / "eagle_mount_views.png"), cv2.cvtColor(np.hstack(views), cv2.COLOR_RGB2BGR))
    print(f"pictures: {out / 'eagle_view_fixed.png'}, {out / 'eagle_mount_views.png'}")
    return bool(good)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=str(PROJECT_ROOT / "docs" / "reports"))
    sys.exit(0 if main(ap.parse_args().out) else 1)
